import java.util.*;

class Solution {
    public List<Integer> spiralOrder(int[][] matrix) {
        List<Integer> ans = new ArrayList<>();
        int m = matrix.length;
        if (m == 0) return ans;
        int n = matrix[0].length;

        boolean[][] visited = new boolean[m][n];
        int[][] dirs = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};   // 右 下 左 上
        int r = 0, c = 0, d = 0;

        for (int step = 0; step < m * n; step++) {
            ans.add(matrix[r][c]);
            visited[r][c] = true;

            int nr = r + dirs[d][0];
            int nc = c + dirs[d][1];
            // 走不通就顺时针换向
            if (nr < 0 || nr >= m || nc < 0 || nc >= n || visited[nr][nc]) {
                d = (d + 1) % 4;
                nr = r + dirs[d][0];
                nc = c + dirs[d][1];
            }
            r = nr;
            c = nc;
        }
        return ans;
    }
}

import java.util.*;

class Solution {
    public List<Integer> spiralOrder(int[][] matrix) {
        List<Integer> ans = new ArrayList<>();
        if (matrix.length == 0) return ans;

        int top = 0, bottom = matrix.length - 1;
        int left = 0, right = matrix[0].length - 1;

        while (top <= bottom && left <= right) {
            // 1. 上边：从左往右
            for (int j = left; j <= right; j++) ans.add(matrix[top][j]);
            top++;

            // 2. 右边：从上往下
            for (int i = top; i <= bottom; i++) ans.add(matrix[i][right]);
            right--;

            // 3. 下边：从右往左（必须先判断，否则单行矩阵会重复输出）
            if (top <= bottom) {
                for (int j = right; j >= left; j--) ans.add(matrix[bottom][j]);
                bottom--;
            }

            // 4. 左边：从下往上（同样必须先判断，否则单列矩阵会重复）
            if (left <= right) {
                for (int i = bottom; i >= top; i--) ans.add(matrix[i][left]);
                left++;
            }
        }
        return ans;
    }
}

import java.util.*;

class Solution {
    public List<Integer> spiralOrder(int[][] matrix) {
        List<Integer> ans = new ArrayList<>();
        int m = matrix.length;
        if (m == 0) return ans;
        int n = matrix[0].length;

        int layers = (Math.min(m, n) + 1) / 2;   // 总圈数
        for (int k = 0; k < layers; k++) {
            int top = k, bottom = m - 1 - k;
            int left = k, right = n - 1 - k;

            // 上边，一定存在
            for (int j = left; j <= right; j++) ans.add(matrix[top][j]);
            // 右边，只在非单行时存在（top+1 开始避免重复左上角）
            if (top < bottom) {
                for (int i = top + 1; i <= bottom; i++) ans.add(matrix[i][right]);
            }
            // 下边：只在非单行时存在（top == bottom 时上边已经把这一行收完了，
            // 再收一遍就是重复 —— 3×4 的矩阵曾经因此在第 2 圈多出一个 6）
            if (top < bottom) {
                for (int j = right - 1; j >= left; j--) ans.add(matrix[bottom][j]);
            }
            // 左边：只在非单列时存在
            if (left < right) {
                for (int i = bottom - 1; i > top; i--) ans.add(matrix[i][left]);
            }
        }
        return ans;
    }
}
